from typing import Annotated
from fastapi import Depends, FastAPI

app = FastAPI()

class Connection:
    def __init__(self):
        self.closed = False

    def close(self):
        self.closed = True

def get_connection():
    conn = Connection()
    try:
        yield conn
    finally:
        conn.close()

@app.get("/status")
def status(conn: Annotated[Connection, Depends(get_connection)]):
    return {"closed": conn.closed}
```

This returns `{"closed": false}` and the connection is closed after the response. The same pattern works with `async def` and `async with` for async resources.

